import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 4

def design(feats):
    # Filter to only include features with significant effect size (> 0.15)
    significant = []
    for i, fid in enumerate(feats.ids):
        if abs(feats.x[:, i].mean() * 2) > 0.15:  # Approximate effect size
            significant.append(i)

    if not significant:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Compute correlations among significant features
    X_sig = feats.x[:, significant]
    corr_matrix = np.corrcoef(X_sig.T)

    # Find highly correlated pairs (|r| >= 0.6)
    correlated_pairs = []
    for i in range(len(significant)):
        for j in range(i+1, len(significant)):
            if abs(corr_matrix[i, j]) >= 0.6:
                fid_i = feats.ids[significant[i]]
                fid_j = feats.ids[significant[j]]
                correlated_pairs.append((fid_i, fid_j))

    # If we have correlated pairs, prefer the one with stronger individual effect
    if correlated_pairs:
        # Score each feature by absolute effect size
        scores = {}
        for i, fid in enumerate(feats.ids):
            scores[fid] = abs(feats.x[:, i].mean() * 2)

        # Remove near-duplicates (keep highest-scoring parent)
        kept = set()
        for a, b in correlated_pairs:
            if scores[a] > scores[b]:
                kept.add(a)
            else:
                kept.add(b)

        # Select top features based on effect sizes
        selected = sorted(kept, key=lambda x: scores[x], reverse=True)
        drivers = tuple(selected[:MAX_DRIVERS])
        columns = tuple(selected[:MAX_DRIVERS])
        products = ()
        loadings = {fid: 1.0 for fid in selected[:MAX_DRIVERS]}

        return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

    # No strong correlations, use top features directly
    scores = [abs(feats.x[:, feats.column(fid)].mean() * 2) for fid in feats.ids]
    top_indices = np.argsort(scores)[::-1][:MAX_DRIVERS]
    top_fids = [feats.ids[i] for i in top_indices]

    return Design(
